-- Generated by scripts/import_ciqual.py from the ANSES Ciqual table (Licence Ouverte).
-- Source: Anses. 2025. Table de composition nutritionnelle des aliments Ciqual.
on conflict (source, source_ref) where source_ref is not null do update set name = excluded.name,
  kcal_100g = excluded.kcal_100g, carbs_100g = excluded.carbs_100g, protein_100g = excluded.protein_100g,
  fat_100g = excluded.fat_100g, sugar_100g = excluded.sugar_100g, fiber_100g = excluded.fiber_100g, salt_100g = excluded.salt_100g;
